/* Scola ağaçkakanı: tek kaynaklı çizim + hareketler. Süs amaçlıdır; XP, seviye ya da doğrulama anlamı taşımaz. */
(function(root){
const ART=`<g class="m-all"><g class="m-tail"><path d="M80 288L22 332L76 322L98 338L126 296Z" fill="#23232d"/></g><g class="m-legs" stroke="#a0724c" stroke-width="7" stroke-linecap="round" stroke-linejoin="round" fill="none"><path d="M136 288L144 322M144 322L116 330M144 322L170 334M144 322L154 340"/><path d="M164 284L174 318M174 318L148 328M174 318L198 330M174 318L184 338"/></g><g class="m-body"><path d="M112 128C84 176 62 226 56 280C96 308 150 308 178 276C198 226 196 168 176 128Z" fill="#33333f"/><path d="M150 112C138 166 164 216 148 270C176 258 198 222 196 174C194 146 184 124 176 112Z" fill="#f7e8c9"/><g class="m-wing"><path d="M122 160C84 174 58 220 52 282C94 268 132 234 144 190Z" fill="#24242e"/><path d="M62 246q7 9 17 1q8 9 18-2q8 8 17-5" stroke="#f7e8c9" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" fill="none"/></g></g><g class="m-head"><circle cx="145" cy="78" r="40" fill="#33333f"/><path d="M150 54C180 46 194 70 186 98C170 110 152 106 146 90Z" fill="#fff"/><g class="m-crest"><path d="M94 66L50 42L90 48L64 14L102 36L104 4L126 32L142 6L152 38L152 70Z" fill="#d62b2b"/></g><g class="m-eye"><circle cx="168" cy="76" r="11" fill="#fff" stroke="#d62b2b" stroke-width="4"/><circle class="m-pupil" cx="168" cy="76" r="5.5" fill="#15151b"/><circle cx="170" cy="73.5" r="1.8" fill="#fff"/></g><path d="M186 72L270 54L192 100Z" fill="#4b4b59"/><path d="M192 86L254 62" stroke="#2b2b35" stroke-width="2.5" stroke-linecap="round"/></g></g>`;
const VIEW={full:'0 0 300 345',head:'44 0 232 132'};
function art(kind,extra){return `<svg class="mascot ${kind==='full'?'':'mascot-head'} ${extra||''}" viewBox="${VIEW[kind]||VIEW.full}" role="img" aria-label="Scola ağaçkakanı" focusable="false">${ART}</svg>`}
if(typeof module==='object'&&module.exports){module.exports={art,ART,VIEW};return}
const calm=()=>root.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
const MOODS={peck:900*3/1000*1000,flap:1000,hop:700,tilt:1500,cheer:1500};
let nodes=[];
function play(el,mood){if(!el||calm())return;Object.keys(MOODS).forEach(m=>el.classList.remove('is-'+m));void el.getBoundingClientRect();el.classList.add('is-'+mood);clearTimeout(el._t);el._t=setTimeout(()=>el.classList.remove('is-'+mood),MOODS[mood]+80)}
function all(mood){nodes=nodes.filter(n=>n.isConnected);nodes.forEach(n=>play(n,mood))}
function scan(scope){(scope||document).querySelectorAll('[data-mascot]:not([data-m-ready])').forEach(h=>{const kind=h.dataset.mascot==='full'?'full':'head';h.dataset.mReady='1';h.innerHTML=art(kind);const svg=h.firstElementChild;nodes.push(svg);if(kind==='full')svg.addEventListener('click',()=>play(svg,'peck'));h.addEventListener('pointerenter',()=>play(svg,kind==='full'?'tilt':'peck'))})}
function look(x,y){nodes=nodes.filter(n=>n.isConnected);nodes.forEach(n=>{const p=n.querySelector('.m-pupil');if(!p)return;const r=n.getBoundingClientRect();if(!r.width)return;const k=n.viewBox.baseVal.width/r.width,dx=(x-(r.left+r.width*.7))*k,dy=(y-(r.top+r.height*.3))*k,d=Math.hypot(dx,dy)||1,m=Math.min(3.4,d/40);p.style.transform=`translate(${(dx/d*m).toFixed(2)}px,${(dy/d*m).toFixed(2)}px)`})}
let idleT;function idle(){clearTimeout(idleT);idleT=setTimeout(()=>{const vis=nodes.filter(n=>n.isConnected&&n.classList.contains('mascot')&&!n.classList.contains('mascot-head')&&n.getBoundingClientRect().height);if(vis.length&&!document.hidden)play(vis[0],['peck','tilt','flap','hop'][Math.floor(Math.random()*4)]);idle()},4500+Math.random()*3500)}
document.addEventListener('pointermove',e=>look(e.clientX,e.clientY),{passive:true});
document.addEventListener('DOMContentLoaded',()=>{scan();idle()});
root.Mascot={art,scan,play:all,cheer:()=>all('cheer'),peck:()=>all('peck')};
})(typeof window!=='undefined'?window:globalThis);
